                stock[p] += produced

        # Step 2: Orders join the queue
        for p in products:
            key = (day, p)
            if key in ledger:
                ordered = ledger[key]['ordered']
                if ordered > 0:
                    open_orders.append([day, p, ordered])

        # Step 3: Dispatch
        open_orders.sort(key=lambda x: (x[0], x[2], x[1]))

        remaining_capacity = capacity
        shipped_today = {p: 0 for p in products}

        i = 0
        while i < len(open_orders):
            order = open_orders[i]
            day_placed, product, remaining_qty = order

            if remaining_qty <= 0:
                i += 1
                continue

            available_stock = stock[product]
            unit_weight = product_weights[product]

            max_by_stock = available_stock
            max_by_capacity = remaining_capacity // unit_weight if unit_weight > 0 else 0
            max_by_order = remaining_qty

            can_ship = min(max_by_stock, max_by_capacity, max_by_order)

            if can_ship > 0:
                order[2] -= can_ship
                stock[product] -= can_ship
                remaining_capacity -= can_ship * unit_weight
                shipped_today[product] += can_ship

                if order[2] <= 0:
                    open_orders.pop(i)
                    continue
                else:
