        open_orders = [o for o in open_orders if o[2] > 0]

        for p in products:
            backordered_sum = sum(o[2] for o in open_orders if o[1] == p)
            results[(day, p)] = {
                'stock': stock[p],
                'backordered': backordered_sum,
                'shipped': shipped_today[p]
            }

    return results

